model.component("comp1").physics("spf").create("wallbc2", "WallBC", 1);
model.component("comp1").physics("spf").feature("wallbc2").selection().set(new int[]{3});
model.component("comp1").physics("spf").feature("wallbc2").set("SlidingWall", "1");
// lid-driven cavity: set the lid velocity in the Sliding wall field (GUI) or via uvwwall

model.component("comp1").physics("spf").create("iwbc1", "InteriorWallBC", 2);
model.component("comp1").physics("spf").feature("iwbc1").selection().set(new int[]{14, 15});
// Application Library: CFD_Module/Single-Phase_Flow/turbulent_mixing (impeller blades as interior walls)

model.component("comp1").geom("geom1").feature("fin").set("action", "assembly");
model.component("comp1").physics("spf").create("fcont1", "Continuity", 2);
// GUI: Flow Continuity 1 > Pair Selection: Identity Boundary Pair 1 (ap1)

model.component("comp1").physics("spf").prop("PhysicalModelProperty").set("RotatingFrame", "1");
// GUI: Rotating Frame 1 > Revolutions per time: 3000[rpm]
// Application Library: Microfluidics_Module/Fluid_Flow/rotating_channel, CFD_Module/Single-Phase_Flow/rotating_turbulent_channel

model.result().numerical().create("int1", "IntSurface");
model.result().numerical("int1").selection().set(new int[]{5, 6, 7, 8});
model.result().numerical("int1").set("expr", new String[]{"-spf.T_stressx", "-spf.T_stressz"});
model.result().numerical("int1").set("descr", new String[]{"Drag force", "Lift force"});
// C_D = F_D/(0.5*rho*U^2*A)

model.component("comp1").physics().create("tds", "DilutedSpecies", "geom1");
// Transport Properties: velocity from spf, diffusion D = 1e-9 m^2/s (+ turbulent mixing)
// Reactions: R_c = 1[mol/(m^3*s)], Inflow: c = 0 at inlet, Outflow at outlet
// Result: intop_out(u*c)/intop_out(u) = mean residence time [s]
// Related: CFD_Module/Applications/water_treatment_basin, Single-Phase_Flow/water_purification_reactor

model.component("comp1").geom("geom1").feature("fin").set("action", "assembly");
model.component("comp1").physics().create("spf", "TurbulentFlowkeps", "geom1");
model.component("comp1").common().create("rot1", "RotatingDomain");
model.component("comp1").common("rot1").selection().set(new int[]{2});
model.study().create("std1");
model.study("std1").create("frrot", "FrozenRotor");
// Application Library: Mixer_Module/Tutorials/modular_mixer_ke, CFD_Module/Single-Phase_Flow/turbulent_mixing

